+package main
+
+import (
+    "fmt"
+    "github.com/c-bata/go-prompt"
+)
+
+func main() {
+    fmt.Println("Testing FindStartOfPreviousWord fix:")
+    
+    // Test case 1: Space-separated words
+    doc1 := &prompt.Document{
+        Text:   "hello world test",
+        Cursor: 16, // Position at end
+    }
+    pos1 := doc1.FindStartOfPreviousWord()
+    fmt.Printf("Space-separated: Expected: 12, Got: %d, Correct: %t\n", pos1, pos1 == 12)
+    
+    // Test case 2: Another space-separated example
+    doc2 := &prompt.Document{
+        Text:   "apple banana",
+        Cursor: 12, // Position at end  
+    }
+    pos2 := doc2.FindStartOfPreviousWord()
+    fmt.Printf("Space-separated 2: Expected: 6, Got: %d, Correct: %t\n", pos2, pos2 == 6)
+    
+    // Test case 3: Tab-separated words (should still work)
+    doc3 := &prompt.Document{
+        Text:   "hello\tworld\ttest",
+        Cursor: 16, // Position at end
+    }
+    pos3 := doc3.FindStartOfPreviousWord()
+    fmt.Printf("Tab-separated: Expected: 12, Got: %d, Correct: %t\n", pos3, pos3 == 12)
+    
+    // Test case 4: Mixed spaces and tabs
+    doc4 := &prompt.Document{
+        Text:   "hello \t world\ttest",
+        Cursor: 18, // Position at end
+    }
+    pos4 := doc4.FindStartOfPreviousWord()
+    fmt.Printf("Mixed separators: Expected: 14, Got: %d, Correct: %t\n", pos4, pos4 == 14)
+    
+    // Test case 5: No separators (single word)
+    doc5 := &prompt.Document{
+        Text:   "hello",
+        Cursor: 5, // Position at end
+    }
+    pos5 := doc5.FindStartOfPreviousWord()
+    fmt.Printf("Single word: Expected: 0, Got: %d, Correct: %t\n", pos5, pos5 == 0)
+    
+    fmt.Println("\nTesting FindStartOfPreviousWordWithSpace fix:")
+    
+    // Test case 6: Multiple spaces
+    doc6 := &prompt.Document{
+        Text:   "hello  world   test",
+        Cursor: 19, // Position at end
+    }
+    pos6 := doc6.FindStartOfPreviousWordWithSpace()
+    fmt.Printf("Multiple spaces: Expected: 14, Got: %d, Correct: %t\n", pos6, pos6 == 14)
+    
+    // Test case 7: Multiple tabs
+    doc7 := &prompt.Document{
+        Text:   "hello\t\tworld\t\t\ttest",
+        Cursor: 20, // Position at end
+    }
+    pos7 := doc7.FindStartOfPreviousWordWithSpace()
+    fmt.Printf("Multiple tabs: Expected: 15, Got: %d, Correct: %t\n", pos7, pos7 == 15)
+    
+    // Test case 8: Mixed multiple spaces and tabs
+    doc8 := &prompt.Document{
+        Text:   "hello \t world \t\t test",
+        Cursor: 23, // Position at end
+    }
+    pos8 := doc8.FindStartOfPreviousWordWithSpace()
+    fmt.Printf("Mixed multiple: Expected: 18, Got: %d, Correct: %t\n", pos8, pos8 == 18)
+}
